from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a list of integers, return their sum and product as a tuple.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    sum_val = 0
    product_val = 1

    for num in numbers:
        sum_val += num
        product_val *= num

    return (sum_val, product_val)
