        return sub_arr == sub_arr[::-1]

    def count_changes(sub_arr):
        changes = 0
        for i in range(len(sub_arr) // 2):
            if sub_arr[i] != sub_arr[-i - 1]:
                changes += 1
        return changes

    if len(arr) == 0:
        return 0

    center = len(arr) // 2
    changes = 0

    if len(arr) % 2 == 0:
        left_sub_arr = arr[:center]
        right_sub_arr = arr[center:]
        changes += count_changes(left_sub_arr)
        changes += count_changes(right_sub_arr)
    else:
        left_sub_arr = arr[:center]
        right_sub_arr = arr[center + 1:]
        changes += count_changes(left_sub_arr)
        changes += count_changes(right_sub_arr)

    return changes

