def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for digit in num:
        if digit in prime_hex_digits:
            if digit.isdigit():
                if is_prime(int(digit)):
                    count += 1
            else:
                if is_prime(ord(digit) - ord('A') + 10):
                    count += 1
    return count

