from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    """ For a provided list of integers, produce a tuple containing the sum of all the integers in the list. It should also include a product of all the integers in the list.
    Empty sum should be equal to 0 and empty product should be equal to 1.
    >>> sum_product([])
    (0, 1)
    >>> sum_product([1, 2, 3, 4])
    (10, 24)
    """
    if not numbers:
        return (0, 1)

    sum_result = 0
    product_result = 1

    for num in numbers:
        sum_result += num
        product_result *= num

    return (sum_result, product_result)

